import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null && !line.trim().isEmpty()) {
            String[] parts = line.trim().split("\\s+");
            if (parts.length < 3) continue;
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            int MOD = Integer.parseInt(parts[2]);

            // Read next line if needed
            // Since input may be multiple lines, read until we get all three
            // For simplicity, assume input is given in one line
            // Otherwise, implement a loop to read until three integers are read

            // Initialize binomial coefficients
            int[][] bin_coeff = new int[m + 1][m + 1];
            for (int i = 0; i <= m; i++) {
                bin_coeff[i][0] = 1;
                for (int j = 1; j <= i; j++) {
                    bin_coeff[i][j] = bin_coeff[i - 1][j - 1] + bin_coeff[i - 1][j];
                    if (bin_coeff[i][j] >= MOD) bin_coeff[i][j] -= MOD;
                }
            }

            int[] prefix_sum = new int[m + 1];
            int[] total_sum = new int[m + 1];
            int[] ways = new int[m + 1];
            int[] sum = new int[m + 1];

            prefix_sum[0] = 0;
            for (int i = 1; i <= m; i++) {
                prefix_sum[i] = prefix_sum[i - 1] + i;
            }

            ways[0] = 1;
            for (int size = 1; size <= m; size++) {
                ways[size] = 0;
                sum[size] = 0;
                for (int split = 0; split < size; split++) {
                    int left = split;
                    int right = size - 1 - split;
                    long prod = ((long) ways[left] * ways[right]) % MOD;

                    // sum_add for ways[size]
                    long val = ((long) (size + 1) * bin_coeff[size - 1][split]) % MOD;
                    val = (val * prod) % MOD;
                    ways[size] = (int) ((ways[size] + val) % MOD);

                    // sum_add for sum[size]
                    long sum_part = 0;
                    sum_part = (sum_part + ((long) sum[left] * ways[right]) % MOD) % MOD;
                    sum_part = (sum_part + ((long) sum[right] * ways[left]) % MOD) % MOD;

                    long sum_add_value = ((long) (size + 1) * bin_coeff[size - 1][split]) % MOD;
                    sum_add_value = (sum_add_value * sum_part) % MOD;
                    sum[size] = (int) ((sum[size] + sum_add_value) % MOD);

                    // total_sum_part
                    long total_sum_part = 0;
                    total_sum_part = (total_sum_part + ((long) prefix_sum[left] * ways[right]) % MOD) % MOD;
                    total_sum_part = (total_sum_part + ((long) prefix_sum[right] * ways[left]) % MOD) % MOD;

                    long total_sum_add = ((long) (size + 1) * bin_coeff[size - 1][split]) % MOD;
                    total_sum_add = (total_sum_add * total_sum_part) % MOD;
                    sum[size] = (int) ((sum[size] + total_sum_add) % MOD);
                }
            }

            int[][] ways2 = new int[n + 1][m + 1];
            int[][] sum2 = new int[n + 1][m + 1];

            ways2[0][0] = 1;
            for (int i = 1; i <= n; i++) {
                for (int j = 0; j <= Math.min(i, m); j++) {
                    ways2[i][j] = ways2[i - 1][j];
                    sum2[i][j] = sum2[i - 1][j];
                    for (int k = 1; k <= j; k++) {
                        int ni = Math.max(0, i - k - 1);
                        int nj = j - k;
                        long valWays = ((long) ways[k] * ways2[ni][nj]) % MOD;
                        valWays = (valWays * bin_coeff[j][k]) % MOD;
                        ways2[i][j] = (int) ((ways2[i][j] + valWays) % MOD);

                        long valSum = ((long) sum[k] * ways2[ni][nj] + (long) ways[k] * sum2[ni][nj]) % MOD;
                        valSum = (valSum * bin_coeff[j][k]) % MOD;
                        sum2[i][j] = (int) ((sum2[i][j] + valSum) % MOD);
                    }
                }
            }

            System.out.println(sum2[n][m]);
        }
    }
